test_cases.test_1:
var arr1 := new int[5][1, 3, 2, 5, 4];
selSort(arr1, 1, 4);
assert sorted_seg(arr1, 1, 4);
assert multiset(arr1[1..4]) == multiset([3, 2, 5]);
assert arr1[..1] == [1] && arr1[4..] == [4];

test_cases.test_2:
var arr2 := new int[3][5, 1, 2];
selSort(arr2, 0, 3);
assert sorted_seg(arr2, 0, 3);
assert multiset(arr2[0..3]) == multiset([5, 1, 2]);
assert arr2[..0] == [] && arr2[3..] == [];

test_cases.test_3:
var arr3 := new int[4][4, 3, 2, 1];
selSort(arr3, 0, 2);
assert sorted_seg(arr3, 0, 2);
assert multiset(arr3[0..2]) == multiset([4, 3]);
assert arr3[..0] == [] && arr3[2..] == [2, 1];

